#include <iostream>
using namespace std;

int main() {
    // Lettura dati di input
    int uno, due, tre;
    int minore;

    cout << "Inserisci tre numeri: ";
    cin >> uno >> due >> tre;

    // Logica del programma
    if (uno < due) {
        if (uno < tre)
            minore = uno;
        else
            minore = tre;
    } else {
        if (due < tre)
            minore = due;
        else
            minore = tre;
    }

    // Scrittura dei dati di output
    cout << "Il numero minore e': " << minore << endl;

    system("pause");
}
